<title>Wishweave Wonders — Level 1</title>
<link rel="stylesheet" href="style.css">
</head>
<body>
<div id="app">
  <main id="game" aria-label="Wishweave Wonders, Level 1">
    <canvas id="view" aria-label="Race view: Purl runs into the loom city"></canvas>

    <!-- HUD: decorative pills ignore pointers so swipes that start over them still reach the game;
         only real buttons take pointer input, and they are never ancestors of the game surface. -->
    <div id="hud" class="hud" hidden>
      <img class="hud-logo" src="assets/ui/logo.webp" alt="Wishweave Wonders" draggable="false">
      <div class="pill hud-phase" id="hud-phase">LEVEL 1 · START</div>
      <div class="hud-counts">
        <div class="pill hud-count purl" id="hud-purl" aria-label="Purl threads held">
          <svg class="flower" viewBox="0 0 40 40" aria-hidden="true"><use href="#ico-flower"/></svg>
          <span class="who">PURL</span><span class="num"><b>0</b>&#8202;/&#8202;3</span>
        </div>
        <div class="pill hud-count loop" id="hud-loop" aria-label="Loop threads held (computer rival)">
          <svg class="flower" viewBox="0 0 40 40" aria-hidden="true"><use href="#ico-flower"/></svg>
          <span class="who">LOOP</span><span class="num"><b>0</b>&#8202;/&#8202;3</span>
        </div>
      </div>
      <div class="pill hud-objective" id="hud-objective" role="status" aria-live="polite">
        <span class="txt">UNFURL THE RIBBON</span>
        <svg class="flag" viewBox="0 0 40 40" aria-hidden="true"><use href="#ico-flag"/></svg>
      </div>
      <div class="race-thread" id="race-thread" aria-hidden="true">
        <i class="bead loop"></i><i class="bead purl"></i>
      </div>
      <div class="hud-results" id="hud-results" hidden>
        <div class="pill result-title"><svg class="orn l" viewBox="0 0 40 40" aria-hidden="true"><use href="#ico-flower"/></svg>LEVEL 1 COMPLETE<svg class="orn r" viewBox="0 0 40 40" aria-hidden="true"><use href="#ico-flower"/></svg></div>
        <div class="pill result-ranks" id="result-ranks"></div>
        <div class="pill result-times" id="result-times"></div>
        <div class="result-wait" id="result-wait" hidden>Loop is still racing<span class="dots"><i>.</i><i>.</i><i>.</i></span></div>
      </div>
      <div class="hud-hint" id="hud-hint" hidden></div>
    </div>

    <button id="btn-pause" class="btn-pause" type="button" aria-label="Pause" hidden></button>

    <div id="countdown" class="countdown" aria-live="assertive" hidden><span></span></div>

    <button id="btn-play-again" class="btn-teal btn-play-again" type="button" hidden>
      <svg class="orn l" viewBox="0 0 40 40" aria-hidden="true"><use href="#ico-flower"/></svg>
      <span class="face">PLAY AGAIN</span>
      <svg class="orn r" viewBox="0 0 40 40" aria-hidden="true"><use href="#ico-flower"/></svg>
    </button>

    <!-- Saved rewards: a visual placeholder only. No balance, exchange rate or payout exists. -->
    <div id="rewards" class="rewards" hidden>
      <span class="rw-label">SAVED REWARDS</span>
      <span class="rw-bar" aria-hidden="true"><i></i></span>
      <span class="rw-slot" aria-hidden="true"></span><span class="rw-slot" aria-hidden="true"></span>
      <button id="btn-cashout" class="btn-cashout" type="button" aria-disabled="true"
              aria-label="Cash out (locked placeholder, no real money)">
        <svg class="lock" viewBox="0 0 24 24" aria-hidden="true"><use href="#ico-lock"/></svg><span>CASH OUT</span>
      </button>
    </div>
    <div id="cashout-note" class="note" role="status" hidden>Cash out is locked — this strip is a placeholder. No real money, nothing is credited.</div>

    <!-- Overlays -->
    <section id="ov-loading" class="overlay ov-loading" role="dialog" aria-label="Loading">
      <div class="card">
        <img class="ov-logo" src="assets/ui/logo.webp" alt="Wishweave Wonders" draggable="false">
        <div class="load-bar" aria-hidden="true"><i id="load-fill"></i></div>
        <p class="load-text" id="load-text">Unrolling the loom city… 0%</p>
        <button id="btn-load-retry" class="btn-cream" type="button" hidden>Retry</button>
      </div>
    </section>

    <section id="ov-start" class="overlay ov-start" role="dialog" aria-labelledby="start-title" hidden>
      <div class="card start-card">
        <img class="ov-logo" src="assets/ui/logo.webp" alt="Wishweave Wonders" draggable="false">
        <h1 id="start-title" class="pill title-pill">LEVEL 1 · THE LOOM CITY</h1>
        <div class="versus">
          <figure class="racer purl"><canvas id="start-purl" width="200" height="200" aria-hidden="true"></canvas>
            <figcaption><b>PURL</b><small>you</small></figcaption></figure>
          <span class="vs" aria-hidden="true">VS</span>
          <figure class="racer loop"><canvas id="start-loop" width="200" height="200" aria-hidden="true"></canvas>
            <figcaption><b>LOOP</b><small>computer rival</small></figcaption></figure>
        </div>
        <p class="rival-note">Loop is a computer-controlled rival.</p>
        <ul class="howto" aria-label="How to play">
          <li><span class="ico ico-tap" aria-hidden="true"></span><span><b>Tap</b> glowing stitches to change the world</span></li>
          <li><span class="ico ico-lr" aria-hidden="true">←&#8202;→</span><span><b>Swipe ← / →</b> to move between lanes</span></li>
          <li><span class="ico ico-up" aria-hidden="true">↑</span><span><b>Swipe ↑</b> to jump</span></li>
          <li><span class="ico ico-goal" aria-hidden="true"><svg viewBox="0 0 40 40"><use href="#ico-flower"/></svg></span><span>Hold all <b>3 wish threads</b> to open the flower gate</span></li>
        </ul>
        <button id="btn-start" class="btn-teal btn-wide" type="button"><span class="face">START RACE</span></button>
        <p class="fine">Saved rewards are a locked placeholder — no real money.</p>
      </div>
    </section>

    <section id="ov-pause" class="overlay ov-pause" role="dialog" aria-labelledby="pause-title" hidden>
      <div class="card pause-card">
        <div class="pause-menu" id="pause-menu">
          <h2 id="pause-title" class="pill title-pill">PAUSED</h2>
          <p class="sub" id="pause-sub">The race is on hold — Loop and Snagling wait too.</p>
          <button id="btn-resume" class="btn-teal btn-wide" type="button"><span class="face">RESUME</span></button>
          <button id="btn-restart" class="btn-cream btn-wide" type="button">RESTART</button>
          <button id="btn-help" class="btn-cream btn-wide" type="button">HOW TO PLAY</button>
        </div>
        <div class="pause-help" id="pause-help" hidden>
          <h2 class="pill title-pill">HOW TO PLAY</h2>
          <ul class="howto">
            <li><span class="ico ico-run" aria-hidden="true">»</span><span>Purl <b>runs by himself</b> into the loom city</span></li>
            <li><span class="ico ico-tap" aria-hidden="true"></span><span><b>Tap</b> a glowing stitch to unfurl ribbons, open carpets, lift tassels and wake the butterfly</span></li>
            <li><span class="ico ico-lr" aria-hidden="true">←&#8202;→</span><span><b>Swipe ← / →</b> to change lane and pick up dropped threads</span></li>
            <li><span class="ico ico-up" aria-hidden="true">↑</span><span><b>Swipe ↑</b> to jump — Snagling can tangle you</span></li>
            <li><span class="ico ico-goal" aria-hidden="true"><svg viewBox="0 0 40 40"><use href="#ico-flower"/></svg></span><span>Hold all <b>3 threads</b> at the flower gate. <b>Loop</b> is a computer-controlled rival.</span></li>
          </ul>
          <p class="fine">Keyboard: ← → ↑ move · Space/Enter taps the stitch · P/Esc pause</p>
          <button id="btn-help-back" class="btn-teal btn-wide" type="button"><span class="face">BACK</span></button>
        </div>
      </div>
    </section>

    <section id="ov-fail" class="overlay ov-fail" role="dialog" aria-labelledby="fail-title" hidden>
      <div class="card fail-card">
        <canvas id="fail-purl" width="200" height="200" aria-hidden="true"></canvas>
        <h2 id="fail-title" class="pill title-pill">ALL TANGLED UP!</h2>
        <p class="sub">Snagling caught Purl with no threads left. Shake it off and try again — saved rewards are unchanged.</p>
        <button id="btn-retry" class="btn-teal btn-wide" type="button"><span class="face">TRY AGAIN</span></button>
      </div>
    </section>

    <section id="ov-error" class="overlay ov-error" role="alertdialog" hidden>
      <div class="card"><h2 class="pill title-pill">SOMETHING SNAGGED</h2><p class="sub" id="error-text"></p></div>
    </section>
  </main>
</div>

