  }

  function showInfo() {
    if (q.get('info') !== '1') return;
    info.hidden = false;
    info.textContent = 'wall ' + wall.toFixed(2) + ' race ' + sim.state.time.toFixed(2) + ' seg ' + sim.state.purl.seg + ' f ' + sim.state.purl.f.toFixed(3);
  }

  function play() {
    let last = performance.now();
